// In OrderHistory.jsx

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from './useAuth';
import './OrderHistory.css';

const OrderHistory = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const { user, token } = useAuth(); // Assume useAuth provides the token

    useEffect(() => {
        if (!user || !token) {
            setLoading(false);
            setError('You must be logged in to view your order history.');
            return;
        }

        const fetchOrders = async () => {
            try {
                // Add the Authorization header to the request
                const response = await axios.get(`http://localhost:8082/api/orders/customer/${user.id}`, {
                    headers: {
                        'Authorization': `Bearer ${token}`
                    }
                });
                setOrders(response.data);
            } catch (err) {
                console.error("Error fetching orders:", err.response || err.message);
                setError('Failed to fetch orders. Please try again later.');
            } finally {
                setLoading(false);
            }
        };

        fetchOrders();
    }, [user, token]); // Add token as a dependency

    // ... rest of the component remains the same
    // ...
};

export default OrderHistory;
